gb9t(){return"\u0641\u0634\u0644 \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0639\u0642\u062f \u2014 \u0642\u062f \u064a\u0643\u0648\u0646 \u0631\u0635\u064a\u062f\u0643 \u063a\u064a\u0631 \u0643\u0627\u0641\u064d."},
gzj(){return"\u0627\u0644\u0637\u0627\u0642\u0645 \u0627\u0644\u0641\u0646\u064a"},
ga6m(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
ga6n(){return"\u0641\u0634\u0644 \u0627\u0644\u062a\u0648\u0642\u064a\u0639 \u2014 \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627"},
gtD(){return"\u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
gW0(){return"\u0627\u0644\u0645\u0624\u062a\u0645\u0631 \u0627\u0644\u0635\u062d\u0641\u064a"},
gaYb(){return"\u0648\u0627\u062b\u0642"},
gaYc(){return"\u0627\u0644\u062e\u0635\u0645 \u0633\u064a\u0633\u0645\u0639 \u0630\u0644\u0643"},
gaYd(){return"\u062f\u0628\u0644\u0648\u0645\u0627\u0633\u064a"},
