gaXQ(){return"\u0627\u0644\u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0627\u0644\u064a"},
gaXI(){return"\u0627\u0643\u062a\u0645\u0644 \u0627\u0644\u0645\u0624\u062a\u0645\u0631"},
