acR(a,b){return a+" \u0645\u0627 \u0632\u0627\u0644 \u0623\u0639\u0644\u0649 \u0645\u0646 \u062d\u062f \u0627\u0644\u0645\u0634\u062a\u0631\u064a. **"+b+"**\u060c \u062b\u0645 \u0627\u0644\u0645\u0633 \u0627\u0644\u0632\u0631 \u0648\u062e\u0641\u0651\u0636 \u0642\u0644\u064a\u0644\u064b\u0627."},
acL(a){return"\u0648\u062f\u0651\u0639\u0646\u0627\u0647: **"+a+"**. \u0623\u0628\u0642\u064a\u062a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u062d\u062f \u0627\u0644\u0645\u0634\u062a\u0631\u064a\u060c \u0633\u0639\u0631 \u062c\u064a\u062f."},
acM(a,b){return"\u0648\u062f\u0651\u0639\u0646\u0627\u0647: **"+a+"**. \u062c\u0639\u0644\u062a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649 \u0645\u0646\u062e\u0641\u0636\u064b\u0627\u061b \u0648\u0643\u0627\u0646 \u062d\u062f \u0627\u0644\u0645\u0634\u062a\u0631\u064a "+b+"."},
LH(a){return a+" \u0623\u063a\u0644\u0642 \u0627\u0644\u0646\u0627\u0641\u0630\u0629."},
gadK(){return"\u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0648\u0627\u0644\u062e\u0637\u0629"},
adM(a,b){return"**"+a+"** \u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0623\u0642\u0648\u0649. \u0627\u0636\u063a\u0637 \u0645\u0637\u0648\u0644\u064b\u0627 \u0639\u0644\u0649 \u0628\u0637\u0627\u0642\u062a\u0647 \u0648\u0623\u0641\u0644\u062a\u0647\u0627 \u0639\u0644\u0649 **"+b+"** \u0641\u064a \u0627\u0644\u0645\u0644\u0639\u0628."},
adL(a,b,c,d){return"\u0623\u062d\u0633\u0646\u062a. **"+a+"** \u0641\u064a \u0627\u0644\u0645\u0644\u0639\u0628 \u0648**"+b+"** \u0628\u062f\u064a\u0644\u061b \u0642\u0648\u0629 \u0627\u0644\u0641\u0631\u064a\u0642 **"+c+" \u2190 "+d+"**. \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0645\u0631\u0627\u0643\u0632 \u0628\u0627\u0644\u062d\u0631\u0643\u0629 \u0646\u0641\u0633\u0647\u0627: \u0623\u0641\u0644\u062a \u0644\u0627\u0639\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0644\u0639\u0628 \u0639\u0644\u0649 \u0644\u0627\u0639\u0628 \u0622\u062e\u0631."},
gadN(){return"\u0627\u0644\u062a\u063a\u064a\u064a\u0631\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0644\u0627 \u062a\u062f\u062e\u0644 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629. \u0627\u0644\u0645\u0633 **\u062d\u0641\u0638**."},
