gacr(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0642\u0627\u0626\u062f. \u0627\u0644\u0642\u0627\u0626\u062f \u064a\u0642\u0648\u0651\u064a \u0627\u0644\u0641\u0631\u064a\u0642 \u0628\u0642\u062f\u0631 \u0642\u064a\u0627\u062f\u062a\u0647. \u0627\u0644\u0645\u0633 \u0628\u0637\u0627\u0642\u0629 **\u0627\u0644\u0642\u0627\u0626\u062f**."},
gacw(){return"\u0627\u062e\u062a\u0631 \u0642\u0627\u0626\u062f\u0643. \u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u0633\u0645\u0627\u0621."},
acv(a,b,c,d){return"\u0623\u0635\u0628\u062d **"+a+"** \u0627\u0644\u0642\u0627\u0626\u062f\u061b \u0642\u064a\u0627\u062f\u062a\u0647 "+b+". \u0623\u0641\u0636\u0644 \u0642\u0627\u0626\u062f \u0641\u064a \u0627\u0644\u0641\u0631\u064a\u0642 \u0647\u0648 **"+c+"** ("+d+"): \u0643\u0644\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0642\u0627\u0626\u062f \u0623\u0641\u0636\u0644 \u0627\u0632\u062f\u0627\u062f \u0627\u0644\u0641\u0631\u064a\u0642 \u0642\u0648\u0629. \u0627\u0644\u0645\u0633 **\u0627\u0644\u0642\u0627\u0626\u062f** \u0644\u0644\u062a\u063a\u064a\u064a\u0631 \u0623\u0648 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 **\u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629**."},
acq(a){return"\u0627\u0644\u0642\u0627\u0626\u062f **"+a+"**: \u0623\u0641\u0636\u0644 \u0642\u0627\u0626\u062f \u0641\u064a \u0627\u0644\u0641\u0631\u064a\u0642. \u0639\u062f \u0627\u0644\u0622\u0646 \u0625\u0644\u0649 **\u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629**\u061b \u0647\u0646\u0627\u0643 \u0628\u0637\u0627\u0642\u0627\u062a \u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u062a\u0631\u0627\u0647\u0627."},
gacs(){return"\u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0623\u0639\u0644\u0649 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u062a\u0628\u064a\u0651\u0646 \u0641\u0626\u0629 \u0627\u0644\u0644\u0627\u0639\u0628: \u0628\u0644\u0627 \u0639\u0644\u0627\u0645\u0629 **\u0639\u0627\u062f\u064a**\u060c \u0646\u062c\u0645\u0629 \u0648\u0627\u062d\u062f\u0629 **\u0646\u062c\u0645**\u060c \u0646\u062c\u0645\u062a\u0627\u0646 **\u0633\u0648\u0628\u0631 \u0633\u062a\u0627\u0631**\u060c \u062b\u0644\u0627\u062b \u0646\u062c\u0648\u0645 **\u0623\u064a\u0642\u0648\u0646\u064a**."},
act(a,b){return"\u0623\u0641\u0636\u0644 \u0644\u0627\u0639\u0628 \u0641\u0626\u0629\u064b \u0641\u064a \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u064a\u0636\u064a\u0641 \u0642\u0648\u0629 \u0635\u063a\u064a\u0631\u0629 \u0644\u0644\u0641\u0631\u064a\u0642. \u0623\u0645\u0633\u0643 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0623\u064a\u0642\u0648\u0646\u064a **"+a+"** \u0645\u0646 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0648\u0623\u0641\u0644\u062a\u0647\u0627 \u0639\u0644\u0649 **"+b+"**."},
